import { describe, it, expect, beforeEach, vi } from 'vitest';
import { readStoredTheme, writeStoredTheme } from './theme';

function makeStorage(initial: Record<string, string> = {}) {
  const data = new Map(Object.entries(initial));
  return {
    getItem: (k: string) => (data.has(k) ? data.get(k)! : null),
    setItem: (k: string, v: string) => { data.set(k, String(v)); },
    removeItem: (k: string) => { data.delete(k); },
    clear: () => data.clear(),
    key: () => null,
    get length() { return data.size; },
  };
}

describe('theme storage', () => {
  beforeEach(() => { vi.stubGlobal('window', { localStorage: makeStorage() }); });

  it('defaults to light when nothing stored', () => {
    expect(readStoredTheme()).toBe('light');
  });
  it('restores a stored dark theme', () => {
    vi.stubGlobal('window', { localStorage: makeStorage({ 'app-theme': 'dark' }) });
    expect(readStoredTheme()).toBe('dark');
  });
  it('ignores invalid stored values', () => {
    vi.stubGlobal('window', { localStorage: makeStorage({ 'app-theme': 'system' }) });
    expect(readStoredTheme()).toBe('light');
  });
  it('round-trips through write then read', () => {
    writeStoredTheme('dark');
    expect(window.localStorage.getItem('app-theme')).toBe('dark');
    expect(readStoredTheme()).toBe('dark');
  });
  it('does not throw when storage throws', () => {
    vi.stubGlobal('window', { localStorage: {
      getItem: () => { throw new Error('denied'); },
      setItem: () => { throw new Error('denied'); },
    } });
    expect(readStoredTheme()).toBe('light');
    expect(() => writeStoredTheme('dark')).not.toThrow();
  });
});
EOF
